class BrowserProspectiveLoad:
    """Load the prospective revision in Chromium through the package-owned browser runner.

    The assets are staged into a fresh temporary directory and served from a random loopback port;
    the child prints one JSON object. A missing ``node``, a missing script, a run that did not
    finish, or an answer this module cannot read are all ``unavailable``: the load did not happen,
    and publication must not treat that as success.
    """

    def __init__(
        self,
        *,
        script: Path | None = None,
        node: str = "node",
        timeout_seconds: float = DEFAULT_TIMEOUT_SECONDS,
        screenshot: Path | None = None,
    ) -> None:
        self._script = script if script is not None else default_load_script()
        self._node = node
        self._timeout = timeout_seconds
        self._screenshot = screenshot

    def load(
        self, *, assets: dict[str, bytes], entrypoint: str, packet: EvidencePacket
    ) -> ProspectiveResult:
        """Stage the exact assets, load them once without a model, and report what was observed."""

        if entrypoint not in assets:
            return ProspectiveResult(
                state="failed",
                kind="browser",
                errors=(f"the revision holds no {entrypoint!r}",),
                detail="nothing was staged: the entrypoint is not among the admitted assets",
            )
        if not self._script.is_file():
            return ProspectiveResult(
                state="unavailable",
                kind="browser",
                errors=(f"the browser load script is absent at {self._script}",),
                detail=(
                    "no browser ran, so this build cannot show the prospective revision loaded; "
                    "publication is refused rather than passed on the static check alone"
                ),
            )
        directory = Path(tempfile.mkdtemp(prefix="ar-prospective-load-"))
        try:
            try:
                _stage(assets, directory)
            except _UnsafeAsset as refusal:
                return ProspectiveResult(
                    state="failed",
                    kind="browser",
                    errors=(str(refusal),),
                    detail="the revision names an asset path that leaves its own staging directory",
                )
            invocation = self._invoke(directory, entrypoint)
        finally:
            shutil.rmtree(directory, ignore_errors=True)
        if not invocation.ran:
            return ProspectiveResult(
                state="unavailable",
                kind="browser",
                errors=(invocation.problem,),
                detail="the load did not run, so nothing about the page was observed",
            )
        result = _read_result(invocation)
        unknown = tuple(
            reference
            for reference in result.evidence_references
            if evidence_reference_state(packet, reference) is None
        )
        if unknown:
            result = replace(
                result,
                state="failed",
                unresolved_references=(*result.unresolved_references, *unknown),
                detail="the rendered DOM cites references absent from the bound evidence packet",
            )
        return result

    def _invoke(self, directory: Path, entrypoint: str) -> _Invocation:
        """Run the child once, answering ``ran=False`` with a named reason when it did not."""

        command = [self._node, str(self._script), "--dir", str(directory), "--entry", entrypoint]
        if self._screenshot is not None:
            command.extend(["--screenshot", str(self._screenshot)])
        try:
            completed = subprocess.run(
                command,
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=self._timeout,
                check=False,
            )
        except FileNotFoundError:
            return _Invocation(
                ran=False,
                problem=(
                    f"no node executable at {self._node!r}, so the browser load could not be "
                    "started"
                ),
            )
        except subprocess.TimeoutExpired:
            return _Invocation(
                ran=False,
                problem=f"the browser load did not finish within {self._timeout:g}s",
            )
        except OSError as error:
            return _Invocation(ran=False, problem=f"the browser load could not start: {error}")
        return _Invocation(
            ran=True,
            stdout=completed.stdout,
            stderr=completed.stderr,
            returncode=completed.returncode,
        )

def check_page(
    assets: dict[str, bytes], *, entrypoint: str, packet: EvidencePacket
) -> ReadinessReport:
    """Check one prospective revision without a model and without a browser."""

    if entrypoint not in assets:
        return ReadinessReport(
            checks=(
                ReadinessCheck("entrypoint", "failed", f"the revision holds no {entrypoint!r}"),
            )
        )
    checks = (
        _check_entry(assets, entrypoint),
        _check_assets(assets),
        _check_evidence(assets, packet),
        _check_motion(assets),
    )
    notes: list[str] = []
    entry_text = assets[entrypoint].decode("utf-8", errors="ignore")
    if _SCRIPT.search(entry_text) or any(
        _SCRIPT.search(payload.decode("utf-8", errors="ignore")) for payload in assets.values()
    ):
        notes.append(
            "the page carries a script; this check is static, so the script is not executed here "
            "(generated scripts run in the sandboxed frame, MIK-R104 rule 8 under D331); the "
            "prospective load that executes it is not this gate"
        )
    return ReadinessReport(checks=checks, notes=tuple(notes))

def policy_digest() -> str:
    """sha256 of the canonical policy, the value a proof record must name."""

    encoded = json.dumps(_policy_payload(), sort_keys=True, separators=(",", ":")).encode()
    return hashlib.sha256(encoded).hexdigest()

def scripts_enabled(proof: IsolationProof) -> bool:
    """Whether generated script execution may be served for this policy (rule 10)."""

    return proof.proven

def record_gaps(payload: dict) -> tuple[str, ...]:
    gaps = (
        _headers_gaps(payload)
        + _artifact_gaps(payload)
        + _matrix_gaps(payload)
        + _request_gaps(payload)
    )
    source = payload.get("source")
    if not isinstance(source, dict):
        gaps.append("no effective-source observations")
    else:
        for key, expected in source_bindings().items():
            if expected == "absent" or source.get(key) != expected:
                gaps.append(f"effective-source {key} is missing or differs")
        for key in ("harness", "proofServer", "panelBundle"):
            if not _HEX.fullmatch(str(source.get(key, ""))):
                gaps.append(f"no {key} source digest")
    return tuple(gaps)

it('starts afresh at a followed intent marker, and its return does not bring the kept family back', async () => {
  const view = await keptState();
  serveTreeRoutes();
  // A file marker now belongs to a card. Select the family that records this range first;
  // the other read family remains kept until the marker is followed.
  fireEvent.click(treeRow(view, R6R_ID));
  await view.findByTestId('review-card-excerpt', undefined);
  const mark = await waitFor(() => {
    const found = view.getAllByTestId('review-hunk-mark');
    expect(found).toHaveLength(1);
    return found[0];
  });
  fireEvent.click(mark);
  const occurrences = within(view.getByTestId('review-hunk-mark-panel')).getAllByTestId(
    'review-hunk-mark-occurrence',
  );
  // INV-ZS9ZS878 as a member of the first family: the kept family itself, followed from a file.
  fireEvent.click(occurrences.find((one) => one.textContent?.includes('(after,'))!);
  await waitFor(() => expect(selectedNode(view) && selectedName(view)).toBe('INV-ZS9ZS878'));
  await waitFor(() => expect(view.queryByTestId('review-reading-pending')).toBeNull());
  // The tree is the marker's subject's own: the second family is not kept beside it.
  expect(families(view)).toEqual([R6R_ID, HBJ_ID]);
  noKept(view);
  // The way back restores the reading position; it brings no kept family back either.
  fireEvent.click(view.getByTestId('review-marker-return'));
  await waitFor(() => expect(view.queryByTestId('review-marker-return')).toBeNull());
  await waitFor(() => expect(families(view)).toEqual([R6R_ID, HBJ_ID]));
  noKept(view);
});

it('starts afresh at the offer to open the task context after a refusal', async () => {
  const view = await keptState();
  const previous = world.answer;
  world.answer = (url, asked) => (asked === subjectOf(ZS9) ? refusal : previous(url, asked));
  fireEvent.click(memberRow(view, R6R_ID, 'INV-ZS9ZS878'));
  const offer = await view.findByTestId('review-source-instead', undefined);
  expect(families(view)).toEqual([R6R_ID, HBJ_ID]);
  fireEvent.click(offer);
  noKept(view);
  expect(families(view)).toEqual([R6R_ID, HBJ_ID]);
  await view.findByTestId('review-center-unselected', undefined);
  expect(families(view)).toEqual([R6R_ID, HBJ_ID]);
  noKept(view);
});

it('starts afresh at an answer of another comparison and says so', async () => {
  const view = await keptState();
  const other = structuredClone(ZS9);
  other.payload!.source.inventory.after_code_tree_id = '0'.repeat(40);
  const previous = world.answer;
  world.answer = (url, asked) => (asked === subjectOf(ZS9) ? other : previous(url, asked));
  // A member row of the kept family: an in-tree selection, answered by another comparison.
  fireEvent.click(memberRow(view, R6R_ID, 'INV-ZS9ZS878'));
  await waitFor(() => expect(view.getByTestId('review-change-status')).toBeTruthy());
  expect(view.getByTestId('review-change-status').textContent).toContain('comparison changed');
  await waitFor(() => expect(families(view)).toEqual([R6R_ID, HBJ_ID]));
  noKept(view);
});

it('opens on the subject asked for with its own families only, and a late catalogue selects the first family afresh', async () => {
  vi.useFakeTimers();
  const catalogue = [R6R, HBJ].map((body) => ({
    selector_kind: 'family',
    selector_id: body.payload!.knowledge.revision_selection!.record_id,
    label: body.payload!.family_context!.entries[0].display_label,
    presence: 'both',
  }));
  let release: (() => void) | undefined;
  const held = new Promise<void>((resolve) => (release = resolve));
  // The catalogue answers after the bounded wait: the task context is read first, then the first
  // family is selected from the late answer.
  world.entries = {
    state: 'entries',
    entries: catalogue,
    total_subjects: 2,
    family_total: 2,
    invariant_total: 0,
  };
  const stubbed = globalThis.fetch;
  vi.stubGlobal('fetch', async (address: string, init?: RequestInit) => {
    if (String(address).includes('/entries')) await held;
    return stubbed(address, init);
  });
  const candidate = R6R.payload!.candidate;
  const view = render(
    <ReviewSurface
      repo={candidate.repository_id}
      master={candidate.master}
      leaf={candidate.leaf_id}
      onBack={() => undefined}
    />,
  );
  await act(async () => { await vi.advanceTimersByTimeAsync(SUBJECT_HOLD_MS); });
  expect(view.getByTestId('review-center-unselected')).toBeTruthy();
  // The hold has expired on the controlled clock; await the released read normally.
  vi.useRealTimers();
  await act(async () => release?.());
  expect(families(view)).toEqual([R6R_ID, HBJ_ID]);
  noKept(view);
  expect((await view.findByTestId('review-center-family', undefined)).dataset.family).toBe(
    R6R_ID,
  );
});

it('keeps the walked tree at the actions rule 9 says change nothing', async () => {
  serveTreeRoutes();
  const view = await keptState();
  const shown = () => [families(view), keptTags(view)];
  const initial = shown();
  const reads = reviewCount();
  // The order control and the filter.
  fireEvent.click(view.getByTestId('review-tree-order'));
  expect(shown()).toEqual(initial);
  fireEvent.click(view.getByTestId('review-tree-order'));
  // The view switch and worklist choose no new subject and retain the walked state.
  fireEvent.click(view.getByTestId('review-tree-view'));
  fireEvent.click(view.getByTestId('review-tree-view'));
  expect(shown()).toEqual(initial);
  fireEvent.click(view.getByRole('button', { name: /^Worklist/ }));
  await view.findByTestId('review-worklist-view', undefined);
  expect(shown()).toEqual(initial);
  fireEvent.click(treeRow(view, HBJ_ID));
  await view.findByTestId('review-center-family', undefined);
  expect(shown()).toEqual(initial);
  // Filtered change-set destinations open over the mounted reviewer and return to it.
  fireEvent.click(view.getByRole('button', { name: /^Changes without an invariant/ }));
  await view.findByTestId('changeset-viewer', undefined);
  expect(shown()).toEqual(initial);
  fireEvent.click(view.getByTestId('changeset-back'));
  await waitFor(() => expect(view.queryByTestId('changeset-viewer')).toBeNull());
  expect(shown()).toEqual(initial);
  expect(reviewCount()).toBe(reads);
});

it('follows and returns as outside selections', () => {
  const { state, calls } = workspace();
  const nav = navigation(calls);
  const moves = workspaceMarkerMoves(state, nav);
  const restore = moves.capture();
  moves.open({ invariant: 'INV-X', invariantKey: 'inv-x', familyKey: 'fam-b', state: 'member' });
  restore();
  expect(vi.mocked(nav.onSelect).mock.calls).toHaveLength(2);
  for (const call of vi.mocked(nav.onSelect).mock.calls) expect(call).toHaveLength(2);
});

export interface SelectionOptions {
  keepTree?: boolean;
  page?: ReviewPageRequest;
}

export function sameGeneration(known: ComparisonGeneration, next: ComparisonGeneration): boolean {
  if (known.trees !== next.trees) return false;
  return known.snapshots === undefined || next.snapshots === undefined
    ? true
    : known.snapshots === next.snapshots;
}

export function comparisonGenerationOf(payload: ReviewPayload): ComparisonGeneration {
  const inventory = payload.source.inventory;
  const comparison = payload.comparison;
  return {
    trees: `${inventory.before_code_tree_id ?? ''}:${inventory.after_code_tree_id ?? ''}`,
    snapshots: comparison?.knowledge_compared
      ? `${comparison.before_snapshot_digest ?? ''}:${comparison.after_snapshot_digest ?? ''}`
      : undefined,
  };
}

