function useRefreshReview(
  workspace: ReturnType<typeof useWorkspaceState>,
  read: ReviewRead,
  refresh: () => void,
): { refreshReview: () => void; retryReview: () => void } {
  const { focusSelection } = workspace;
  // The read on screen when the refresh was asked: a failure shown then is not the refresh's own.
  const asked = useRef<ReviewRead | null>(null);
  // The failed or refused read of a refresh, once its request is dropped.
  const failed = useRef<ReviewRead | null>(null);
  const settle = useCallback(
    (shown: ReviewRead) => {
      const unanswered = shown.phase === 'failed' || shown.phase === 'refused';
      if (unanswered && shown !== asked.current && focusSelection.current?.scrollOnly) {
        focusSelection.current = null;
        failed.current = shown;
      }
    },
    [focusSelection],
  );
  useEffect(() => settle(read), [read, settle]);
  const refreshReview = () => {
    workspace.beginSelection(false);
    focusSelection.current = {
      from: document.activeElement,
      after: workspace.treeIntent.id,
      scrollOnly: true,
    };
    asked.current = read;
    refresh();
  };
  const retryReview = () => {
    // A retry made in the turn that shows the failure comes before that turn's effects.
    settle(read);
    if (failed.current === read) refreshReview();
    else refresh();
  };
  return { refreshReview, retryReview };
}

function subjectSelection(parts: {
  navigation: ReturnType<typeof useReviewNavigation>;
  workspace: ReturnType<typeof useWorkspaceState>;
  setInstead: (failure: ReviewFailure | null) => void;
  setSelection: (page: ReviewPageRequest | undefined) => void;
}) {
  const { navigation, workspace, setInstead, setSelection } = parts;
  const selectSubject = (
    subject: ReviewSubject | undefined,
    context?: FamilySelection,
    options?: SelectionOptions,
  ) => {
    workspace.focusSelection.current = {
      from: document.activeElement,
      after: workspace.treeIntent.id,
    };
    workspace.beginSelection(options?.keepTree === true);
    navigation.onSelect(subject);
    setInstead(null);
    setSelection(options?.page);
    workspace.setChosen(context ?? null);
  };
  // The offer to open the task context after a refusal is an outside selection too.
  const openTaskContext = (failure: ReviewFailure) => {
    workspace.beginSelection(false);
    navigation.onSelect(undefined);
    workspace.setChosen(null);
    setSelection(undefined);
    setInstead(failure);
  };
  return { selectSubject, openTaskContext };
}

function useSurface({
  repo,
  master,
  leaf,
  selectorKind: initialKind,
  selectorId: initialId,
  history,
  onBack,
}: ReviewTarget & { onBack: () => void }) {
  const navigation = useReviewNavigation({
    repo,
    master,
    leaf,
    selectorKind: initialKind,
    selectorId: initialId,
    history,
  });
  const selectorKind = navigation.subject?.kind;
  const selectorId = navigation.subject?.id;
  const [instead, setInstead] = useState<ReviewFailure | null>(null);
  const [selection, setSelection] = useState<ReviewPageRequest | undefined>(undefined);
  const workspace = useWorkspaceState();
  // One cache per mounted surface: reclaimed with it (see `ReviewReadCache`).
  const [cache] = useState(() => new ReviewReadCache());
  const { selectSubject, openTaskContext } = subjectSelection({
    navigation,
    workspace,
    setInstead,
    setSelection,
  });
  const cycle = useReviewReadCycle({
    repo,
    master,
    leaf,
    selectorKind,
    selectorId,
    history,
    instead,
    selection,
    hold: navigation.settling,
    cache,
  });
  const { read, retained, frame } = cycle;
  useReviewMemoryWatch({ repo, master, leaf, history }, cycle, navigation.engage);
  const key = targetKeyOf(
    repo,
    master,
    leaf,
    instead,
    selectorKind,
    selectorId,
    selection,
    history,
  );
  const coherent = retained !== null && retained.key === key ? retained.payload : null;
  const shown = shownPayload(read, coherent);
  useObservedComparison(navigation.observeComparison, shown);
  const asked = instead === null ? navigation.subject : undefined;
  const problem = problemOf(read);
  const { refreshReview, retryReview } = useRefreshReview(workspace, read, cycle.refresh);
  // The owner's failure or refusal for the requested subject, rendered in the reading area.
  const problemBlock = (label: string) =>
    problem === null ? null : (
      <ReviewProblemBlock
        origin={read.phase === 'refused' ? 'refusal' : 'failure'}
        problem={problem}
        subject={label}
        onRetry={retryFor(read, retryReview)}
        onOpenTaskContext={insteadFor(read, problem, instead, openTaskContext)}
      />
    );
  return {
    ...{ repo, master, leaf, selectorKind, selectorId, history, onBack, navigation, selectSubject },
    ...{ instead, setInstead, selection, setSelection, workspace, cache, frame, coherent, shown },
    ...{ read, carried: cycle.carried, refreshReview, retryReview, problem },
    openTaskContext,
    reading:
      frame === null || shown !== null
        ? null
        : readingStatusOf(read, key, asked, navigation.catalogue, problemBlock),
  };
}

function WorkspaceRail({
  payload,
  state,
  navigation,
  chosen,
  walk,
  laneRead,
  subject,
  changesOpen,
  leafTrees,
  prefetchCards,
}: {
  payload: ReviewPayload;
  repo: string;
  master: string;
  leaf: string;
  state: WorkspaceState;
  navigation?: ReviewNavigationState;
  chosen: FamilySelection | null;
  walk: Walk;
  laneRead: LaneRead<ReviewUnexplainedLane> | null;
  // The answered subject (none while another is read): an intent marker's unknown-membership target.
  subject?: ReviewNavigationState['subject'];
  changesOpen: boolean;
  leafTrees: ReturnType<typeof useReviewTrees>;
  prefetchCards: (invariants: string[]) => void;
}) {
  const tree = walkedTreeOf(walk, payload, navigation?.catalogue);
  const families = (
    <FamilyRailContext
      payload={payload}
      state={state}
      walked={tree}
      // While a lane destination is on screen, no family node is the current selection.
      chosen={state.worklist ? null : chosen}
      selectable={Boolean(navigation?.catalogue.entries?.length)}
      subject={subject}
      navigation={navigation}
      traversalEnabled={!changesOpen}
      prefetchCards={prefetchCards}
      leafTrees={leafTrees}
    />
  );
  return (
    <aside className={rail} data-review-tree-panel>
      <div className={shell}>
        {navigation ? (
          <ReviewNavigation
            {...navigation}
            walkedEntries={tree.entries}
            summaryCounts={laneCounts(laneRead)}
            codeSummary={codeChangesSummary(navigation.catalogue.outline, leafTrees, treeComparisonNumber(payload.limitations))}
            destinations={
              <ReviewDestinations
                payload={payload}
                laneRead={laneRead}
                state={state}
                leafTrees={leafTrees}
              />
            }
          >
            {families}
          </ReviewNavigation>
        ) : (
          families
        )}
      </div>
    </aside>
  );
}

function restore(
  position: Position,
  state: WorkspaceState,
  navigation?: ReviewNavigationState,
): void {
  if (navigation) {
    navigation.onSelect(position.subject, position.chosen ?? undefined);
    // The return focuses the originating marker, not the tree's selection.
    state.focusSelection.current = null;
  } else {
    state.setChosen(position.chosen);
  }
  // After the subject: choosing a subject leaves the lane, and the return may be into the lane.
  state.setWorklist(position.worklist);
  state.setOpenPath(position.openPath);
  state.setLayout(position.layout);
  state.setFullFile(position.fullFile);
}

function openTarget(
  target: MarkTarget,
  state: WorkspaceState,
  navigation?: ReviewNavigationState,
): void {
  const context: FamilySelection | undefined = target.familyKey
    ? { familyId: target.familyKey, memberRevisionId: target.memberRevisionKey }
    : undefined;
  state.setOpenPath(null);
  if (navigation) navigation.onSelect({ kind: 'invariant', id: target.invariantKey }, context);
  else state.setChosen(context ?? null);
}

function absorb(walk: Walk, payload: ReviewPayload): Walk {
  const next = comparisonGenerationOf(payload);
  const moved = walk.generation !== null && !sameGeneration(walk.generation, next);
  const entries = payload.family_context?.entries ?? [];
  const known = moved || walk.replaceNext ? [] : walk.families;
  return {
    ...walk,
    generation: moved ? next : carriedGeneration(walk.generation, next),
    source: payload,
    families: mergeFamilies(known, entries, subjectOf(payload), payload),
    current: new Set(entries.map((entry) => entry.family_id)),
    replaceNext: false,
    notice: moved && keptFamilies(walk).length > 0 ? MOVED_NOTICE : null,
  };
}

function rebase(walk: Walk, payload: ReviewPayload, scope: string, intent: TreeIntent): Walk {
  if (walk.scope !== scope) return absorb(emptyWalk(scope, intent.id), payload);
  if (walk.intent === intent.id) return walk;
  if (intent.keep) return { ...walk, intent: intent.id, replaceNext: false };
  return { ...absorb(emptyWalk(scope, intent.id), payload), replaceNext: true };
}

export function useWorkspaceState(): WorkspaceState {
  const [chosen, setChosen] = useState<FamilySelection | null>(null);
  const [query, setQuery] = useState('');
  const [layout, setLayout] = useState<DiffMode>(() => window.matchMedia('(max-width: 40rem)').matches ? 'inline' : 'split');
  const [fullFile, setFullFile] = useState(false);
  const [openPath, setOpenPath] = useState<string | null>();
  const [worklist, setWorklist] = useState(false);
  const opener = useRef<HTMLElement | null>(null);
  const center = useRef<HTMLDivElement>(null);
  const focusSelection = useRef<FocusRequest | null>(null);
  const [treeIntent, setTreeIntent] = useState<TreeIntent>({ id: 0, keep: false });
  const beginSelection = (keepTree: boolean) =>
    setTreeIntent((previous) => ({ id: previous.id + 1, keep: keepTree }));
  const openFromCenter = (path: string) => {
    opener.current = document.activeElement as HTMLElement | null;
    setOpenPath(path);
  };
  const closePath = (path: string | null) => {
    if (path !== null) opener.current = document.activeElement as HTMLElement | null;
    setOpenPath(path);
    if (path === null) opener.current?.focus();
  };
  const choose = (selection: FamilySelection | null) => {
    setChosen(selection);
    setWorklist(false);
    if (selection) revealCenter(center);
  };
  return {
    chosen,
    setChosen: choose,
    query,
    setQuery,
    layout,
    setLayout,
    fullFile,
    setFullFile,
    openPath,
    openFromCenter,
    closePath,
    setOpenPath,
    center,
    worklist,
    setWorklist,
    focusSelection,
    treeIntent,
    beginSelection,
  };
}

def _prune_locked(self) -> None:
    records = self.records()
    if len(records) <= MAX_RETAINED_ATTEMPTS:
        return
    for attempt in reversed(records[MAX_RETAINED_ATTEMPTS:]):
        if attempt.state in LIVE_STATES:
            continue
        self.remove(attempt)

@pytest.mark.parametrize("depth", [1, 2])
@pytest.mark.parametrize("operation", ["read", "write", "mkdir", "unlink", "remove", "lock"])
def test_native_io_keeps_the_admitted_physical_parent(tmp_path, monkeypatch, depth, operation):
    root = tmp_path / "owned" / "parent" / "child"
    root.mkdir(parents=True)
    (root / "value.txt").write_bytes(b"owned")
    (root / "branch").mkdir()
    (root / "branch" / "value.txt").write_bytes(b"owned")
    swapped = root.parents[depth - 1]
    foreign = tmp_path / "foreign"
    shutil.copytree(swapped, foreign)
    foreign_leaf = foreign / root.relative_to(swapped)
    (foreign_leaf / "value.txt").write_bytes(b"foreign")
    before = {p.relative_to(foreign): p.read_bytes() for p in foreign.rglob("*") if p.is_file()}
    fired = False

    def swap():
        nonlocal fired
        if not fired:
            swapped.rename(swapped.with_name(swapped.name + "-held"))
            swapped.symlink_to(foreign, target_is_directory=True)
            fired = True

    owner, name, accepts = {
        "read": (os, "open", lambda path: Path(path).name == "value.txt"),
        "write": (io, "open", lambda path: Path(path).name.startswith(".value.txt.")),
        "mkdir": (os, "mkdir", lambda path: str(path) == "new"),
        "unlink": (os, "unlink", lambda path: str(path) == "value.txt"),
        "remove": (shutil, "rmtree", lambda path: str(path) == "branch"),
        "lock": (os, "open", lambda path: Path(path).name == "resource.lock"),
    }[operation]
    native = getattr(owner, name)

    def interleave(path, *args, **kwargs):
        if accepts(path):
            swap()
        return native(path, *args, **kwargs)

    with monkeypatch.context() as patch:
        patch.setattr(owner, name, interleave)
        _act(operation, root)
    assert fired, "the interleave must occur at the real native operation"
    after = {p.relative_to(foreign): p.read_bytes() for p in foreign.rglob("*") if p.is_file()}
    assert after == before

def path_segment(value: str, *, name: str) -> str:
    """One path segment, refusing anything that could leave the directory it names."""

    if not value or "/" in value or "\\" in value or value.startswith(".") or value in {".", ".."}:
        raise PathRefused(f"{name} {value!r} is not one path segment")
    return value

@contextmanager
def directory_fd(path: Path, *, create: bool = False) -> Iterator[int]:
    """Open an absolute directory, refusing a symlink at any component."""

    absolute = path.absolute()
    if ".." in absolute.parts:
        raise OSError("a descriptor path must not contain '..'")
    descriptor = os.open(absolute.anchor, _DIRECTORY)
    try:
        for part in absolute.parts[1:]:
            if create:
                with suppress(FileExistsError):
                    os.mkdir(part, dir_fd=descriptor)
            child = os.open(part, _DIRECTORY, dir_fd=descriptor)
            os.close(descriptor)
            descriptor = child
        yield descriptor
    finally:
        os.close(descriptor)

class Presenter:
    """One page's presenter state: its attempts, their records, and the confined publication."""

    def __init__(  # noqa: PLR0913 - one page's own identity and its two ports
        self,
        config: McpRuntimeConfig,
        *,
        repository_id: str,
        task: str,
        leaf_id: str,
        frame_id: str,
        runner: PresenterRunner | None = None,
        limits: FrameLimits | None = None,
        prospective: ProspectiveLoad | None = None,
        clock: Any = None,
    ) -> None:
        self._config = config
        self._repository_id = repository_id
        self._task = task
        self._leaf_id = leaf_id
        self._frame_id = frame_id
        self._limits = limits or FrameLimits()
        self._clock = clock or _now
        # MIK-R104 rule 14: a ready pointer moves only after the exact prospective revision was
        # loaded once without a model. The shipped default is a real browser load; a caller that
        # cannot run one passes a port that says ``unavailable`` rather than a port that says
        # ``loaded``.
        self._prospective: ProspectiveLoad = prospective or BrowserProspectiveLoad()
        self._runner: PresenterRunner = runner or NativePresenterHarness(
            config,
            identity=HostIdentity(
                repository_id=repository_id, task=task, leaf_id=leaf_id, frame_id=frame_id
            ),
            clock=self._clock,
        )
        self._attempts: AttemptStore | None = None

    def _host(self) -> PresenterHost | None:
        return _host_port(self._runner)

    def _host_for(self, attempt: PresenterAttempt) -> tuple[PresenterHost, str] | None:
        """The host and the exact session its calls must name, or ``None`` for a local record."""

        host = self._host()
        session_id = attempt.session_id
        if host is None or not session_id:
            return None
        return host, session_id

    # -- store and paths -----------------------------------------------------------------------

    @property
    def scope(self) -> FrameScope:
        root = task_root(self._config, self._repository_id, self._task)
        return frame_scope(root, self._leaf_id, self._frame_id)

    def _directory(self) -> Path:
        directory = (
            presenter_root(self.scope.task_root)
            / path_segment(self._leaf_id, name="leaf")
            / path_segment(self._frame_id, name="frame")
        )
        try:
            return self.scope.guard(directory, label="presenter directory")
        except FrameRefused as refusal:
            raise PresenterRefused("unsafe-presenter-path", str(refusal)) from refusal

    @property
    def _store(self) -> AttemptStore:
        """The page's durable attempts, attached on first use so construction still does no IO."""

        if self._attempts is None:
            self._attempts = AttemptStore(
                self._config, scope=self.scope, directory=self._directory(), clock=self._clock
            )
        return self._attempts

    def _working(self, attempt: PresenterAttempt) -> Path:
        try:
            return guard_path(
                presenter_work_base(self._config),
                Path(attempt.working_directory),
                label="attempt working folder",
            )
        except PathRefused as refusal:
            raise PresenterRefused("unsafe-working-path", str(refusal)) from refusal

    # -- records -------------------------------------------------------------------------------

    def _attached(self) -> AttemptStore | None:
        """The store, or ``None`` when this page's own directory is not admissible.

        A read is not a write: an unsafe presenter directory makes the page look empty to a
        reader, exactly as A2's facade behaved, rather than raising on the first read. Writes
        still refuse by name, because a refused write is not an empty page.
        """

        try:
            return self._store
        except PresenterRefused:
            return None

    def attempts(self) -> tuple[PresenterAttempt, ...]:
        """The displayed attempts, newest first, bounded by :data:`MAX_ATTEMPTS`."""

        store = self._attached()
        if store is None:
            return ()
        return tuple(store.records()[:MAX_ATTEMPTS])

    def read(self, attempt_id: str) -> PresenterAttempt | None:
        store = self._attached()
        return None if store is None else store.read(attempt_id)

    def current(self) -> PresenterAttempt | None:
        """The newest live attempt, else the newest retained one: the default panel view."""

        store = self._attached()
        return None if store is None else store.current()

    def live(self) -> PresenterAttempt | None:
        """The latest-created attempt still open, independent of the displayed window."""

        store = self._attached()
        return None if store is None else store.live()

    def by_request(self, request_id: str) -> PresenterAttempt | None:
        """Reconcile one request identity across every retained record, not the shown window."""

        store = self._attached()
        return None if store is None else store.by_request(request_id)

    def by_session(self, session_id: str) -> PresenterAttempt | None:
        """Find one attempt by its recorded host session, across every retained record."""

        store = self._attached()
        return None if store is None else store.by_session(session_id)

    def _record_path(self, attempt_id: str) -> Path:
        return self._store.record_path(attempt_id)

    def _evidence_path(self, attempt_id: str) -> Path:
        return self._store.evidence_path(attempt_id)

    def _read_evidence(self, attempt_id: str, expected: str) -> EvidencePacket | None:
        return self._store.read_evidence(attempt_id, expected)

    # -- authoring -----------------------------------------------------------------------------

    def start(  # noqa: PLR0913 - one start states the assignment's own inputs
        self,
        *,
        caller: str,
        request_id: str,
        activation: str,
        evidence: EvidencePacket,
        focus: str,
        regenerate_from: int | None = None,
        predecessor_attempt: str | None = None,
    ) -> PresenterAttempt:
        """Start one explicit authoring attempt, or refuse by name.

        The request identity is the reconciliation key: a repeat returns the attempt it already
        created, a second live attempt is refused, and no start happens without explicit developer
        activation. Regeneration copies the retained revision's own assets into the new working
        folder and records its ancestry; missing retained bytes are a refusal, never a fresh start.
        The runner receives the exact selected design text with its source and sha256, behind the
        non-authority fence.
        """

        binding = FrameBinding.from_packet(evidence.comparison)
        self._admit_binding(binding)
        if evidence.comparison.repository_id != self._repository_id:
            raise PresenterRefused("foreign-comparison", "the evidence names another repository")
        if activation != "explicit":
            raise PresenterRefused(
                "not-activated",
                "authoring starts only from the explicit Generate control; a mount, a reload, a "
                "saved page or a status read starts no model",
            )
        attempt, assignment, launch_model = self._admit_start(
            _StartRequest(
                caller=caller,
                request_id=request_id,
                binding=binding,
                evidence=evidence,
                focus=focus,
                regenerate_from=regenerate_from,
                predecessor_attempt=predecessor_attempt,
            )
        )
        if assignment is None or launch_model is None:
            if attempt.state == "started" and (attempt.detail or "").startswith(
                "start-outcome-unknown"
            ):
                reconcile = getattr(self._runner, "reconcile", None)
                if callable(reconcile):
                    try:
                        receipt = cast(RunnerReceipt, reconcile(attempt, self._working(attempt)))
                    except StartOutcomeUnknown:
                        return attempt
                    return self._store.mutate(
                        attempt.attempt_id,
                        lambda current: receipt_changes(current, receipt, attempt.model or ""),
                    )
            return attempt
        return self._run(attempt, assignment=assignment, launch_model=launch_model)

    def _admit_binding(self, binding: FrameBinding) -> None:
        if (binding.task_id, binding.leaf_id) != (self._task, self._leaf_id):
            raise PresenterRefused(
                "foreign-comparison",
                f"the evidence names {binding.task_id}/{binding.leaf_id}; this page explains "
                f"{self._task}/{self._leaf_id}",
            )

    def _admit_start(
        self, request: _StartRequest
    ) -> tuple[PresenterAttempt, str | None, str | None]:
        """Admit and durably record one new attempt, then release the lock before any host call."""

        with self._store.locked():
            existing = self._store.by_request(request.request_id)
            if existing is not None:
                return existing, None, None
            reclaimed = self._store.ledger().get(request.request_id)
            if reclaimed is not None:
                raise PresenterRefused(
                    "attempt-record-reclaimed",
                    f"request {request.request_id} created attempt {reclaimed}, whose record has "
                    "been reclaimed under the retention ceiling; this request is reconciled to it "
                    "and starts no second session",
                )
            live = self._store.live()
            if live is not None:
                raise PresenterRefused(
                    "in-flight",
                    f"attempt {live.attempt_id} is still {live.state} for this comparison; "
                    "reconcile it before a second start",
                )
            launch = presenter_launch(self._config, repository_id=self._repository_id)
            if launch.state != "ok":
                raise PresenterRefused("launch-choice-unavailable", launch.detail)
            design = design_text(self._config, self._repository_id)
            instructions, composition = compose_capability_capsule(
                CAPABILITY, launch.provenance.get("notes", {})
            )
            instructions_digest = digest_bytes(instructions.encode())
            attempt = self._open_attempt(
                caller=request.caller,
                request_id=request.request_id,
                binding=request.binding,
                evidence=request.evidence,
                focus=request.focus,
                launch_model=launch.model or "",
                design=design,
                instructions_digest=instructions_digest,
                regenerate_from=request.regenerate_from,
                predecessor_attempt=request.predecessor_attempt,
                disclosures=_design_disclosures(design),
            )
            attempt = attempt.model_copy(
                update={
                    "instruction_composition": instruction_metadata(composition),
                    "launch_provenance": launch.provenance,
                }
            )
            self._store.write_locked(attempt)
        return attempt, _compose_assignment(instructions, design), launch.model or ""

    def _open_attempt(  # noqa: PLR0913 - one attempt record's own decided fields
        self,
        *,
        caller: str,
        request_id: str,
        binding: FrameBinding,
        evidence: EvidencePacket,
        focus: str,
        launch_model: str,
        design: DesignText,
        instructions_digest: str,
        regenerate_from: int | None,
        predecessor_attempt: str | None,
        disclosures: tuple[str, ...],
    ) -> PresenterAttempt:
        attempt_id = f"att-{digest_bytes(f'{request_id}:{self._clock()}'.encode())[:16]}"
        working = presenter_working_root(
            self._config,
            repository_id=self._repository_id,
            task=self._task,
            leaf_id=self._leaf_id,
            frame_id=self._frame_id,
            attempt_id=attempt_id,
        )
        make_directory(presenter_work_base(self._config), working, label="attempt working folder")
        try:
            if regenerate_from is not None:
                seed_from_revision(self.scope, working, regenerate_from)
            evidence_bytes = canonical_json_bytes(
                json.loads(evidence.model_dump_json(by_alias=True))
            )
            write_file(self._store.evidence_path(attempt_id), evidence_bytes)
        except (PresenterRefused, OSError):
            with suppress(OSError):
                remove_directory(working)
            raise
        now = self._clock()
        conversation = tuple(
            ConversationEntry(
                at=now,
                role="presenter",
                comparison=binding.comparison_reference,
                text=text,
            )
            for text in disclosures
        )
        return PresenterAttempt(
            attempt_id=attempt_id,
            request_id=request_id,
            caller=caller,
            repository_id=self._repository_id,
            task=self._task,
            leaf_id=self._leaf_id,
            frame_id=self._frame_id,
            comparison=binding,
            evidence_digest=digest_bytes(evidence_bytes),
            focus=focus,
            state="started",
            created_at=now,
            updated_at=now,
            working_directory=str(working),
            parent_revision=regenerate_from,
            predecessor_attempt=predecessor_attempt,
            model=launch_model,
            design_source=design.source,
            design_sha256=design.sha256,
            design_words=design.words,
            instructions_sha256=instructions_digest,
            conversation=conversation,
        )

    def _run(
        self, attempt: PresenterAttempt, *, assignment: str, launch_model: str
    ) -> PresenterAttempt:
        """Hand the attempt to the confined runner and keep whatever it answered."""

        working = self._working(attempt)
        try:
            receipt = self._runner.start(attempt, assignment, working)
        except StartOutcomeUnknown as refusal:
            detail = f"start-outcome-unknown: {refusal}; retry the same request to reconcile"
            return self._store.mutate(attempt.attempt_id, lambda _current: {"detail": detail})
        except PresenterRefused as refusal:
            captured = refusal
            return self._store.mutate(
                attempt.attempt_id, lambda current: failed_changes(current, captured)
            )
        return self._store.mutate(
            attempt.attempt_id,
            lambda current: receipt_changes(current, receipt, launch_model),
        )

    def note_activity(self, attempt_id: str, *, kind: str, text: str) -> PresenterAttempt:
        """Append one attributable activity line, bounded and typed."""

        if kind not in _ACTIVITY_KINDS:
            raise PresenterRefused("unknown-activity", f"{kind!r} is not an activity kind")

        def change(current: PresenterAttempt) -> dict[str, Any]:
            entry = ActivityEntry(at=self._clock(), kind=kind, text=text)
            return {"activity": (*current.activity, entry)[-MAX_ACTIVITY:]}

        return self._store.mutate(attempt_id, change)

    def say(
        self,
        attempt_id: str,
        *,
        role: Literal["presenter", "developer", "system-owner"],
        text: str,
        revision: int | None = None,
    ) -> PresenterAttempt:
        """Send one conversation turn; a configured host answers it and its receipt is recorded."""

        if role not in {"presenter", "developer", "system-owner"}:
            raise PresenterRefused("unknown-role", f"{role!r} is not a conversation role")
        attempt = self._store.require(attempt_id)
        fallback = ConversationEntry(
            at=self._clock(),
            role=role,
            comparison=attempt.comparison.comparison_reference,
            revision=revision,
            text=text,
        )
        sent = text
        if attempt.published_revision is not None:
            manifest = revision_manifest(self.scope.frame_dir, attempt.published_revision)
            if manifest is None or manifest.authoring.request_id != attempt.request_id:
                raise PresenterRefused(
                    "publication-unavailable", "the exact publication receipt is unavailable"

class NativePresenterHarness:
    def __init__(self, config: McpRuntimeConfig, *, identity: HostIdentity, clock: Any = None):
        self._config = config
        self._identity = identity
        self._clock = clock or (lambda: datetime.now(UTC).isoformat())

    def _call(self, command: str, payload: dict[str, Any]) -> dict[str, Any]:
        try:
            return bridge_call(self._config, command, payload)
        except PaseoBridgeFailure as error:
            if command == "agent-create" and error.code in {
                "paseo_bridge_timeout",
                "paseo_bridge_invalid_reply",
                "paseo_daemon_unreachable",
                "paseo_send_outcome_unknown",
            }:
                raise StartOutcomeUnknown(error.code, str(error)) from error
            raise PresenterRefused(error.code, str(error)) from error

    def start(self, attempt: PresenterAttempt, instructions: str, working: Path) -> RunnerReceipt:
        try:
            provider, options = qualified_launch(self._config, attempt.repository_id)
        except PaseoBridgeFailure as error:
            raise PresenterRefused(error.code, str(error)) from error
        if provider != "claude":
            raise PresenterRefused(
                "presenter-confinement-unavailable",
                f"the selected provider {provider!r} has no qualified presenter tool boundary",
            )
        evidence = presenter_root(task_root(self._config, attempt.repository_id, attempt.task))
        evidence = (
            evidence / attempt.leaf_id / attempt.frame_id / f"{attempt.attempt_id}.evidence.json"
        )
        payload = read_bounded(
            evidence, MAX_RECORD_BYTES, reason="evidence-too-large", detail="evidence"
        )
        if digest_bytes(payload) != attempt.evidence_digest:
            raise PresenterRefused(
                "evidence-changed", "the admitted packet changed before host start"
            )
        write_output(working, "host/assignment.txt", instructions.encode())
        write_output(working, "host/evidence.json", payload)
        grants = {
            "working": str(working),
            "attempt": attempt.attempt_id,
            "inputs": {
                "evidence.json": digest_bytes(payload),
                "assignment.txt": digest_bytes(instructions.encode()),
            },
        }
        write_output(working, "host/grants.json", json.dumps(grants).encode())
        workspace = self._call("workspace-open", {"cwd": str(working)})
        # Stable identity: a lost create reply reconciles the same host session on retry/restart.
        agent_id = str(uuid.uuid5(uuid.NAMESPACE_URL, str(working)))
        server = {
            "type": "stdio",
            "command": sys.executable,
            "args": [
                "-P",
                "-m",
                "agents_remember.canvas.presenter_tools",
                "--working",
                str(working),
            ],
            "env": {
                key: value
                for key, value in os.environ.items()
                if key.startswith("XDG_")
                or key in {"PYTHONPYCACHEPREFIX", "AR_CANVAS_PROSPECTIVE_LOAD", "AR_PLAYWRIGHT"}
            },
        }
        create = {
            "agentId": agent_id,
            "idempotencyKey": f"review-presenter:{agent_id}",
            "workspaceId": workspace["workspace"]["id"],
            "provider": provider,
            "title": f"Review presenter · {attempt.leaf_id}",
            "labels": {
                "ar.capability": "review-presenter",
                "ar.presenter-attempt": attempt.attempt_id,
            },
            "mcpServers": {"review-presenter": server},
            "toolPolicy": {
                "preapproved": [
                    {"kind": "mcp", "server": "review-presenter", "tool": name}
                    for name in TOOL_NAMES
                ]
            },
            "systemPrompt": "Use only your review-presenter tools. This is a presentation capability, not an AR role. Read assignment.txt and evidence.json through read_input before authoring. Documentation is not evidence.",
            "prompt": f"Author the requested review page. Focus: {attempt.focus}. Read both admitted inputs. Use assets to inspect any retained starting page before revising it. Write assets/index.html and any local assets, and render the exact draft. Explain what you inspected and the result in this conversation. Do not publish or change review/acceptance state.",
        }
        for option, native in (
            ("model", "model"),
            ("effort", "thinkingOptionId"),
            ("mode", "modeId"),
            ("featureValues", "featureValues"),
        ):
            if options.get(option):
                create[native] = options[option]
        prepared = {
            "create": create,
            "provenance": {
                "choices": launch_choice_metadata(options["choices"]),
                "permissionBoundary": {
                    "provider": provider,
                    "builtInTools": [],
                    "inheritedMcpServers": False,
                    "toolServer": server,
                    "readGrants": grants["inputs"],
                    "writeRoot": str(working),
                },
            },
        }
        write_output(working, "host/prepared-start.json", json.dumps(prepared).encode())
        return self.reconcile(attempt, working)

    def reconcile(self, attempt: PresenterAttempt, working: Path) -> RunnerReceipt:
        """Repeat the immutable native create, with no settings reread or new identity."""
        prepared = json.loads(
            read_bounded(
                working / "host/prepared-start.json",
                MAX_RECORD_BYTES,
                reason="prepared-start-too-large",
                detail="the original native start request",
            )
        )
        create = prepared["create"]
        if create["labels"]["ar.presenter-attempt"] != attempt.attempt_id:
            raise PresenterRefused("prepared-start-conflict", "the request names another attempt")
        reply = self._call("agent-create", create)
        return RunnerReceipt(
            execution_id=create["agentId"],
            session_id=create["agentId"],
            model=reply["agent"].get("model"),
            detail="real host presenter reconciled with confined tools; no publication implied",
            provenance={
                **prepared["provenance"],
                "observed": reply["agent"],
                "hostServerId": reply["serverId"],
            },
        )

    def _receipt(self, session_id: str, reply: dict[str, Any], detail: str) -> HostReceipt:
        return HostReceipt(
            session_id=session_id,
            message_id=str(uuid.uuid4()),
            state=str(reply.get("agent", {}).get("status", "unknown")),
            detail=detail,
            execution_id=session_id,
        )

    def message(self, session_id: str, *, role: str, text: str) -> HostReceipt:
        lane = "system-owner" if role == "system-owner" else "developer"
        message_id = str(uuid.uuid4())
        reply = self._call(
            "agent-send",
            {"agentId": session_id, "text": f"[{lane}] {text}", "messageId": message_id},
        )
        if not reply["delivery"]["delivered"]:
            raise PresenterRefused("presenter-message-refused", reply["delivery"]["detail"])
        return HostReceipt(session_id, message_id, "running", "the host took the conversation turn")

    def status(self, session_id: str) -> HostStatus:
        view = self._call("agent-state", {"agentId": session_id})["agent"]
        if view is None:
            raise PresenterRefused("presenter-session-missing", session_id)
        return HostStatus(
            session_id,
            "",
            view["status"],
            None,
            session_id,
            None,
            self._clock(),
            json.dumps(view),
            bool(view["archivedAt"]),
        )

    def transcript(self, session_id: str) -> tuple[HostTurn, ...]:
        reply = self._call("presenter-transcript", {"agentId": session_id})
        if reply.get("available") is False:
            raise PresenterRefused("presenter-transcript-unavailable", reply["detail"])
        return tuple(
            HostTurn(
                row["at"],
                "system-owner" if row["text"].startswith("[system-owner]") else row["role"],
                "system-owner" if row["text"].startswith("[system-owner]") else "developer",
                row["text"],
            )
            for row in reply["entries"]
        )

    def resume(self, session_id: str) -> HostReceipt:
        reply = self._call("agent-resume", {"agentId": session_id})
        if reply.get("agent") is None or reply["agent"].get("archivedAt"):
            raise PresenterRefused(
                "presenter-session-unavailable", "the exact session is missing or archived"
            )
        return self._receipt(session_id, reply, json.dumps(reply["resume"]))

    def cancel(self, session_id: str, *, reason: str) -> HostReceipt:
        reply = self._call("presenter-cancel", {"agentId": session_id})
        return self._receipt(session_id, reply, f"host cancellation acknowledged: {reason}")

    def archive(self, session_id: str) -> HostReceipt:
        reply = self._call("agent-archive", {"agentId": session_id})
        return self._receipt(session_id, reply, "host archive acknowledged")

def create_server(working: Path) -> FastMCP:
    tools = AuthoringTools(working)
    server = FastMCP("review-presenter")

    @server.tool()
    def inputs() -> dict:
        """List exact admitted input names and digests. There is no arbitrary filesystem reader."""
        return tools.grants["inputs"]

    @server.tool()
    def read_input(name: str) -> str:
        """Read evidence.json or assignment.txt, with its admitted digest checked."""
        return tools.read(name)

    @server.tool()
    def source(side: str, path: str, start: int = 1, end: int = 100) -> dict:
        """Read a relative path at one of the packet's four exact trees, through bounded R102 IO.

        No repository, HEAD or revision argument exists. Refusals and unavailable history are
        receipts, not permission to read today's checkout. Never writes or executes compared code.
        """
        packet = EvidencePacket.model_validate_json(tools.read("evidence.json"))
        return read_source(packet, side, path, start=start, end=end)

    @server.tool()
    def assets(relative: str | None = None, offset: int = 0) -> dict:
        """List/read this attempt's own assets; exact read chunks are bounded to 12000 characters."""
        return tools.assets(relative, offset)

    @server.tool()
    def write_asset(relative: str, text: Annotated[str, Field(max_length=1048576)]) -> dict:
        """Write UTF-8 presentation output relative to assets/, never an absolute/protected path."""
        body = text.encode()
        tools.write(relative, body)
        return {"path": relative, "sha256": digest_bytes(body), "bytes": len(body)}

    @server.tool()
    def carry_kit(paths: list[str]) -> dict:
        """Carry kit-relative files (e.g. shiki/4.5.0/shiki-kit.js) and their required notices."""
        return tools.carry(paths)

    @server.tool()
    def documentation(url: str, offset: int = 0) -> dict:
        """Fetch bounded read-only authoring documentation. This surface is NEVER review evidence."""
        return tools.documentation(url, offset)

    @server.tool()
    def render() -> list:
        """Load the exact draft in Chromium with reduced motion; return diagnostics and its picture."""
        report, picture = tools.render()
        result: list[Any] = [json.dumps(report)]
        if picture is not None:
            result.append(Image(data=picture, format="png"))
        return result

    return server

class RefuseCrossOriginWrites:
    """The ASGI middleware. A refusal answers ``403`` and never reaches a route."""

    def __init__(self, app: ASGIApp) -> None:
        self._app = app

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        refusal = refusal_reason(scope)
        if refusal is None:
            await self._app(scope, receive, send)
            return
        await _refuse(scope, receive, send, refusal)

class RefuseForeignHosts:
    """Rule 15's rebinding guard: every route, reads included, answers only its own host and port."""

    def __init__(self, app: ASGIApp) -> None:
        self._app = app

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        refusal = host_refusal(scope)
        if refusal is None:
            await self._app(scope, receive, send)
            return
        await _refuse(scope, receive, send, refusal)

def document_headers(origin: str, *, session: str, scripts: bool) -> dict[str, str]:
    """Every header a frame document carries, including the policy and a missing-cache answer."""

    return {
        **FRAME_HEADERS,
        "Content-Security-Policy": frame_csp(origin, session=session, scripts=scripts),
        "Cache-Control": "no-store",
    }

def frame_sandbox(*, scripts: bool) -> str:
    """The sandbox token set. Never carries ``allow-same-origin``."""

    return _SANDBOX_SCRIPTS if scripts else _SANDBOX_INERT

def page_asset(hosts: CanvasHosts, request: Request) -> Response:
    """One asset of the revision the live session was opened for, and nothing else.

    The route addresses no revision, frame or task: the session is the only address, so a caller
    cannot choose another revision's bytes, another frame's asset or another task's file. The store's
    own ``open_asset`` decides containment, digest and media type from that one revision's manifest
    (L104-B03).
    """

    value = request.path_params["session"]
    session = hosts.sessions.get(value)
    if session is None:
        return _not_live(hosts, value)
    path = request.path_params["asset_path"]
    try:
        scope = _frame_scope(
            hosts, session.repository_id, session.master, session.leaf_id, session.frame_id
        )
        payload = open_asset(scope, session.revision, path)
    except (PathRefused, FrameRefused, ValueError) as error:
        return _refusal("asset-unavailable", str(error), status=404)
    return Response(
        content=payload,
        headers=asset_headers(_asset_media_type(scope, session.revision, path)),
    )

def page(hosts: CanvasHosts, request: Request) -> Response:
    """The one document one live session may load, with its policy headers."""

    value = request.path_params["session"]
    session = hosts.sessions.get(value)
    if session is None:
        return _not_live(hosts, value)
    try:
        scope = _frame_scope(
            hosts, session.repository_id, session.master, session.leaf_id, session.frame_id
        )
        payload = open_asset(scope, session.revision, session.entrypoint)
    except (PathRefused, FrameRefused, ValueError) as error:
        return _refusal("revision-unavailable", str(error), status=404)
    return Response(
        content=bound_document(payload, session),
        media_type="text/html",
        headers=document_headers(
            _origin(request), session=session.session, scripts=session.scripts
        ),
    )

def _remember_request_locked(self, request_id: str, attempt_id: str) -> None:
    ledger = self.ledger()
    ledger[request_id] = attempt_id
    while len(ledger) > MAX_REQUEST_LEDGER:
        ledger.pop(next(iter(ledger)))
    write_file(
        self._ledger_path(),
        canonical_json_bytes(ledger),
    )

def parse_frame_message(raw: bytes, *, binding: Binding) -> AcceptedMessage:
    """Validate one raw request against one session's binding, or refuse it by name.

    The envelope's own identity fields are checked against the binding: a message that names another
    session, revision or comparison is refused as the forgery it is.
    """

    decoded = _decoded(raw)
    try:
        message = FrameMessage.model_validate(decoded)
    except ValidationError as error:
        raise ProtocolRefusal(
            "malformed", f"the envelope is invalid: {error.errors()[0]}"
        ) from error
    if message.protocol_version != PROTOCOL_VERSION:
        raise ProtocolRefusal(
            "wrong-version",
            f"protocol version {message.protocol_version} is not the registered {PROTOCOL_VERSION}",
        )
    if message.type not in FRAME_OPS:
        raise ProtocolRefusal(
            "unknown-op", f"{message.type!r} is not one of the registered operations"
        )
    if message.session != binding.session:
        raise ProtocolRefusal("foreign-session", "the message names another session")
    if message.revision != binding.revision:
        raise ProtocolRefusal(
            "stale-revision",
            f"the message names revision {message.revision}; this channel serves "
            f"{binding.revision}",
        )
    if message.comparison != binding.comparison:
        raise ProtocolRefusal(
            "foreign-comparison",
            "the message names another comparison than the revision it was served with",
        )
    return AcceptedMessage(
        operation=message.type,
        request_id=message.request_id,
        payload=_PAYLOAD_RULES[message.type](message.payload),
    )

def session_message(hosts: CanvasHosts, request: Request, raw: bytes) -> JSONResponse:
    """One host-protocol request: bound, bounded, refused by name, applied only after all three."""

    value = request.path_params["session"]
    session = hosts.sessions.get(value)
    if session is None:
        return _not_live(hosts, value)
    binding = Binding(
        session=session.session, revision=session.revision, comparison=session.comparison
    )
    try:
        # The bucket is charged before the parse: every request that reaches the route is bounded
        # work, so a malformed or replayed flood costs one debit and is then refused rate-limited
        # without a parse (L104-B08).
        session.budget.charge()
        message = parse_frame_message(raw, binding=binding)
        session.budget.admit(message)
    except ProtocolRefusal as refusal:
        session.budget.note_refusal(refusal.reason, refusal.detail)
        return JSONResponse(
            {"state": "refused", "reason": refusal.reason, "detail": refusal.detail}
        )
    if message.operation != "open-evidence":
        stale = _superseded(hosts, session)
        if stale is not None:
            session.budget.note_refusal("stale-revision", stale)
            return JSONResponse({"state": "refused", "reason": "stale-revision", "detail": stale})
    if message.operation in {"status", "ready"}:
        if message.operation == "status":
            session.budget.last_status = message.payload
        return JSONResponse({"state": "accepted", "operation": message.operation})
    if message.operation == "request-explanation":
        return _explanation_requested(hosts, session, message.payload)
    return _evidence_requested(hosts, session, message.payload)

def kit_assets(paths: list[str] | tuple[str, ...], root: Path | None = None) -> dict[str, bytes]:
    """The named kit files as revision assets, under the contract path a page names them by.

    ``paths`` are kit-relative (``shiki/4.5.0/shiki-kit.js``); each returned key is prefixed with
    :data:`KIT_CONTRACT_PREFIX`, so a page's ``kit/shiki/4.5.0/shiki-kit.js`` reference resolves
    inside its own revision. An unknown path, a wrong size or a wrong digest is refused by name.
    """

    base = root or KIT_ROOT
    index = kit_files(base)
    carried: dict[str, bytes] = {}
    selected = set(paths)
    for entry in kit_manifest(base):
        if selected.intersection(item.path for item in (*entry.files, *entry.notices)):
            # Selecting a library carries its attribution and dependency notices with the
            # revision. The generated page cannot silently strip a bundled dependency's licence.
            selected.update(item.path for item in entry.notices)
            selected.update(
                item.path for item in entry.files if not item.path.endswith((".js", ".css"))
            )
    for path in sorted(selected):
        item = index.get(path)
        if item is None:
            raise KitRefused("kit-unknown-file", f"{path!r} is not a file this kit ships")
        try:
            carried[item.contract_path] = _read_verified(path, item, base)
        except OSError as error:
            raise KitRefused("kit-file-absent", f"{path}: {error}") from error
    return carried

def _read_verified(path: str, expected: KitFile, root: Path) -> bytes:
    payload = (root / path).read_bytes()
    if len(payload) != expected.bytes:
        raise KitRefused(
            "kit-size-mismatch",
            f"{path} is {len(payload)} bytes; the manifest declares {expected.bytes}",
        )
    digest = hashlib.sha256(payload).hexdigest()
    if digest != expected.sha256:
        raise KitRefused(
            "kit-digest-mismatch",
            f"{path} hashes to {digest}; the manifest declares {expected.sha256}",
        )
    return payload

